   "a": {
    "unit_id": "BLLD_45-2019.D118.K1",
    "tieu_de_dieu": "Nội quy lao động",
    "khoan_cha": "",
    "chu_don_vi": "Người sử dụng lao động phải ban hành nội quy lao động, nếu sử dụng từ 10 người lao động trở lên thì nội quy lao động phải bằng văn bản."
   },
   "b": {
    "unit_id": "BLLD_45-2019.D118.K3",
    "tieu_de_dieu": "Nội quy lao động",
    "khoan_cha": "",
    "chu_don_vi": "Trước khi ban hành nội quy lao động hoặc sửa đổi, bổ sung nội quy lao động, người sử dụng lao động phải tham khảo ý kiến của tổ chức đại diện người lao động tại cơ sở đối với nơi có tổ chức đại diện người lao động tại cơ sở."
   },
   "vi_tu_chung": [
    "issue_internal_labor_regulations"
   ]
  },
  {
   "cap_id": "P0281",
   "a": {
    "unit_id": "BLLD_45-2019.D122.K5",
    "tieu_de_dieu": "Nguyên tắc, trình tự, thủ tục xử lý kỷ luật lao động",
    "khoan_cha": "",
    "chu_don_vi": "Không xử lý kỷ luật lao động đối với người lao động vi phạm kỷ luật lao động trong khi mắc bệnh tâm thần hoặc một bệnh khác làm mất khả năng nhận thức hoặc khả năng điều khiển hành vi của mình."
   },
   "b": {
    "unit_id": "BLLD_45-2019.D175.K1.b",
    "tieu_de_dieu": "Các hành vi bị nghiêm cấm đối với người sử dụng lao động liên quan đến thành lập, gia nhập và hoạt động của tổ chức đại diện người lao động tại cơ sở",
    "khoan_cha": "Phân biệt đối xử đối với người lao động, thành viên ban lãnh đạo của tổ chức đại diện người lao động tại cơ sở vì lý do thành lập, gia nhập hoặc hoạt động tổ chức đại diện người lao động, bao gồm:",
    "chu_don_vi": "Sa thải, kỷ luật, đơn phương chấm dứt hợp đồng lao động, không tiếp tục giao kết hoặc gia hạn hợp đồng lao động, chuyển người lao động làm công việc khác;"
   },
   "vi_tu_chung": [
    "discipline_employee_for_labor_violations"
   ]
  },
  {
   "cap_id": "P0282",
   "a": {
    "unit_id": "BLLD_45-2019.D128.K3",
    "tieu_de_dieu": "Tạm đình chỉ công việc",
    "khoan_cha": "",
    "chu_don_vi": "Trường hợp người lao động bị xử lý kỷ luật lao động, người lao động cũng không phải trả lại số tiền lương đã tạm ứng."
   },
   "b": {
    "unit_id": "BLLD_45-2019.D128.K4",
    "tieu_de_dieu": "Tạm đình chỉ công việc",
    "khoan_cha": "",
    "chu_don_vi": "Trường hợp người lao động không bị xử lý kỷ luật lao động thì được người sử dụng lao động trả đủ tiền lương cho thời gian bị tạm đình chỉ công việc."
